        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool ReadNarrowBatch(ref ReadBatch batch, ref Narrow value)
        {
            if (!batch.SerializeBits(ref value.N, 3))
            {
                return false;
            }
            return true;
        }

